P={
"google-gmail":dict(
 answer="Google never hands over passwords. If you set up Inactive Account Manager, up to 10 people you chose can download the data you picked once your account goes inactive. Without it, immediate family or a representative can ask Google to close the account, release funds or provide some data, decided case by case.",
 facts=["Passwords: never shared","Plan ahead: Inactive Account Manager, up to 10 contacts","No plan: deceased-user request (close, funds or data)","Inactivity: personal accounts can be deleted after 2 years"],
 need=["Your ID and the deceased person's Gmail address","A death certificate","For data requests, Google may ask for further legal documents such as a court order"],
 timeline="Inactive Account Manager runs only after the inactivity period you set. Deceased-user requests are reviewed individually and Google gives no fixed timeframe.",
 lost=["Passwords and login access","Account contents after a closure request: Google says it can't process a later request for the contents once you choose to close the account","Everything, if the account is deleted under the 2-year inactivity policy"],
 extra=[("Should I request data or closure first?","Data first. Google says that if you close the account it can't later turn over its contents."),("Does Inactive Account Manager include YouTube?","Yes. Google's own example lists Blogger, Drive, Mail and YouTube among the data a contact can be given.")],
 sources=[GS,GI,GP],related=["/platforms/youtube/","/platforms/google-photos/","/guides/google-takeout-export/"]),
"google-photos":dict(
 answer="Google Photos lives inside your Google Account, so it follows Google's rules. Add Photos to Inactive Account Manager and your chosen contacts can download it after the inactivity period. Without a plan, family must use Google's deceased-user data request, which isn't guaranteed. Shared albums and Takeout backups made now are the safest route.",
 facts=["Covered by Inactive Account Manager","No plan: deceased-user data request, reviewed case by case","Inactive accounts can be deleted after 2 years","Back up now with Google Takeout"],
 need=["Death certificate","Your ID and the account address","Possibly further legal documents for a data request"],
 timeline="Contacts get a download link only after the inactivity period you chose. Data requests have no published timeframe.",
 lost=["Photos only stored in an account deleted for inactivity","Contents of an account already closed at family's request"],
 extra=[("How do I back up my Google Photos?","Use Google Takeout and select Google Photos; store the archive offline and in a second location."),("Can family request photos without a plan?","They can ask through Google's deceased-user form, but Google decides each request after review.")],
 sources=[GI,GS,GP],related=["/guides/google-takeout-export/","/platforms/google-gmail/","/platforms/apple-icloud/"]),
"apple-icloud":dict(
 answer="With a Legacy Contact, that person uses their access key and your death certificate to request your iCloud data, such as photos, messages, notes, files and backups. Without one, Apple requires legal documentation, often a court order; Apple says Australia and some other countries accept alternative documents. Keychain passwords and purchased media are never included.",
 facts=["Legacy Contact needs: access key + death certificate","Excluded: iCloud Keychain and purchased media","No Legacy Contact: court order or local equivalent","Australia: Apple accepts alternative documentation"],
 need=["Legacy Contact route: the access key and a death certificate","Without a Legacy Contact: death certificate plus a court order or the documentation Apple accepts in your country","To delete the account: your own Apple Account and the required legal documents"],
 timeline="Apple reviews and verifies documentation before acting and doesn't publish a fixed processing time.",
 lost=["iCloud Keychain passwords, passkeys and payment info","Purchased movies, music, books and subscriptions","Some end-to-end encrypted data may need a device passcode","A passcode-locked device can't be unlocked by Apple without erasing it"],
 extra=[("Can Apple unlock a dead person's iPhone?","No. Apple says it can't remove a device passcode without erasing the device. It may help remove Activation Lock so the device can be reused."),("Is a court order needed in Australia?","Apple says Australia and some other jurisdictions accept alternative documentation instead of a court order; check Apple's page for your country.")],
 sources=[AL,AD],related=["/guides/apple-legacy-contact-setup/","/guides/access-deceased-persons-phone-and-accounts/","/tools/apple-legacy-contact/"]),
"facebook":dict(
 answer="Facebook either memorialises your profile, adding 'Remembering' next to your name, or permanently deletes it, depending on what you chose in advance. A legacy contact you name can manage parts of a memorialised profile, such as a pinned tribute post, but can't log in or read your messages. Family can request memorialisation with proof of death.",
 facts=["Options: memorialise or delete","Legacy contact: can't log in or read messages","You must be 18+ to choose a legacy contact","Set in Accounts Centre → Memorialisation"],
 need=["Memorialisation: proof of death such as an obituary","Removal: proof you're immediate family or the executor, such as a death certificate"],
 timeline="Requests are reviewed by Facebook; no fixed timeframe is published.",
 lost=["Private messages","Login access for anyone, including the legacy contact"],
 extra=[("Can I choose deletion instead?","Yes. In the Memorialisation settings you can choose to have your account permanently deleted after your death."),("Is Instagram the same?","No. Instagram offers memorialisation and removal requests but works differently. See our Instagram page.")],
 sources=[("Facebook Help: About legacy contacts","https://www.facebook.com/help/1568013990080948"),("Meta: Settings you can manage in Accounts Center","https://www.meta.com/help/accounts-center/841741830388205/")],related=["/platforms/instagram/","/platforms/whatsapp/","/guides/digital-estate-checklist/"]),
"instagram":dict(
 answer="Instagram memorialises an account when it receives proof of death, such as an obituary. Nobody can log into a memorialised account, and its posts stay visible to the same audience. Verified immediate family can instead ask for the account to be removed, using documents such as a death certificate. Instagram doesn't give out passwords.",
 facts=["Memorialise: anyone, with proof of death","Remove: verified immediate family","No login access for anyone","Back up your own photos via Download your information"],
 need=["Memorialisation: proof of death, such as an obituary link","Removal: documents such as the death certificate and proof you're immediate family or the estate representative"],
 timeline="Instagram reviews each request; no fixed timeframe is published.",
 lost=["Direct messages","Login access"],
 extra=[("How do I save my Instagram photos?","Use Accounts Centre → Your information and permissions → Download your information."),("Can anyone request memorialisation?","Yes, with proof of death. Removal is limited to verified immediate family.")],
 sources=[("Instagram Help: Deceased person's account","https://help.instagram.com/264154560391256")],related=["/platforms/facebook/","/platforms/whatsapp/","/platforms/x-twitter/"] ),
"x-twitter":dict(
 answer="X doesn't memorialise accounts and won't give anyone access, including family. An immediate family member or a person authorised to act for the estate can ask X to deactivate the account. X then asks for details of the deceased, a copy of the requester's ID and a death certificate. Download your own archive now if you want posts kept.",
 facts=["No memorialisation","No account access for family","Deactivation on request","Needs: requester ID + death certificate"],
 need=["Details of the deceased and their @username","A copy of your government ID","A copy of the death certificate"],
 timeline="X emails instructions after the request is submitted; no fixed processing time is published.",
 lost=["Direct messages","Posts, once the account is deactivated, unless someone downloaded an archive beforehand"],
 extra=[("Can I keep a copy of my posts for family?","Yes. Request your archive in Settings → Your account → Download an archive of your data, and store it with your digital estate plan."),("Who can ask X to deactivate an account?","An immediate family member or someone authorised to act on behalf of the estate.")],
 sources=[("X Help: Contact X about a deceased family member's account","https://help.x.com/en/rules-and-policies/contact-x-about-a-deceased-family-members-account")],related=["/platforms/facebook/","/platforms/linkedin/","/guides/digital-estate-checklist/"]),
"microsoft-outlook":dict(
 answer="Microsoft won't release a deceased person's Outlook.com or OneDrive content without a valid subpoena or court order, and even then it isn't guaranteed. You don't need to report the death. If nobody signs in, Outlook.com and OneDrive are frozen after 1 year, with content deleted soon after, and the Microsoft account expires after 2 years.",
 facts=["Content release: subpoena or court order only","Outlook.com/OneDrive frozen after 1 year inactive","Account expires after 2 years inactive","Closed accounts can be reopened within 60 days"],
 need=["If you have the password: nothing; you can close the account yourself","Without access: a valid subpoena or court order served on Microsoft's registered agent (Microsoft won't act on faxed or emailed requests)"],
 timeline="1 year of inactivity: Outlook.com and OneDrive frozen and content deleted shortly after. 2 years: the Microsoft account expires. After a closure, 60 days to change your mind before permanent deletion.",
 lost=["Email and OneDrive files, after the 1-year freeze and deletion","All account data 60 days after closure"],
 extra=[("Does Microsoft have a legacy contact feature?","Microsoft's official page on deceased users doesn't describe one. It points family to closing the account (if they have the password) or a court order. Plan with a password manager instead."),("How do I stop a dead person's Microsoft subscriptions?","Microsoft suggests cancelling via the bank: close the card or account, or revoke the payment authorisation.")],
 sources=[MS],related=["/best/best-password-managers-emergency-access/","/guides/access-deceased-persons-phone-and-accounts/","/platforms/dropbox/"]),
"linkedin":dict(url="https://www.linkedin.com/help/linkedin/answer/a1336663",
 answer="LinkedIn offers two options: close the account or memorialise the profile. Anyone connected or related by last name can report a member as deceased, and LinkedIn will memorialise the profile. Closing the account requires someone with legal authority to act for the estate, a death certificate and probate-type documents. LinkedIn never gives out passwords.",
 facts=["Memorialise: report as deceased (connection or same surname)","Close: needs legal authority","Memorialised accounts are locked","Data deleted within 30 days of closure"],
 need=["Member's full name, profile URL and your relationship","Helpful: their email, date of death and an obituary link","To close: death certificate plus Letters of Administration, Letters Testamentary, Letters of Representation or another court order"],
 timeline="After closure, LinkedIn says it can take up to 30 days to fully delete the data.",
 lost=["Login access and messages","All profile data after closure"],
 extra=[("Can family get a LinkedIn password?","No. LinkedIn says it won't disclose usernames or passwords to anyone, including family, under any circumstances."),("What's the difference between memorialising and closing?","Memorialising keeps the profile visible but locked; closing deletes it. Closing requires legal authority.")],
 sources=[("LinkedIn Help: Memorialize or close the account of a deceased member","https://www.linkedin.com/help/linkedin/answer/a1336663"),("LinkedIn Help: Deceased LinkedIn member","https://www.linkedin.com/help/linkedin/answer/a1380121")],related=["/platforms/facebook/","/platforms/x-twitter/","/guides/australian-digital-estate-guide/"]),
"coinbase":dict(
 answer="Crypto held on Coinbase forms part of your estate. Coinbase doesn't support beneficiary designations for individual accounts, so heirs need to know the account exists. The executor files an Executor Services claim with a death certificate, proof of authority such as probate or letters of administration, photo ID, and a signed letter naming the Coinbase account to receive the assets.",
 facts=["No beneficiary designation","Claim via Coinbase Executor Services","Needs probate or equivalent authority","Recipient may need a Coinbase account"],
 need=["Official death certificate","Probate, Letters Testamentary, Letters of Administration, or a small estate affidavit where accepted","Current government photo ID of the person named in those documents","A signed letter directing transfer to a named Coinbase account and email"],
 timeline="Coinbase reviews claims after receiving the documents; no fixed timeframe is published.",
 lost=["Funds in self-custody wallets if nobody has the seed phrase. No company can recover those."],
 extra=[("Do heirs need a Coinbase account?","Usually. The assets are transferred to a Coinbase account named in the executor's letter."),("Can I name a beneficiary on Coinbase?","No. Coinbase says beneficiary designations aren't supported for individual accounts.")],
 sources=[("Coinbase Help: Claim a decedent's Coinbase account","https://help.coinbase.com/en/coinbase/managing-my-account/other/how-do-i-gain-access-to-a-deceased-family-members-coinbase-account")],related=["/best/best-crypto-inheritance-tools/","/tools/casa/","/guides/australian-digital-estate-guide/"]),
"dropbox":dict(
 answer="Dropbox may give access to a deceased person's files, but only after reviewing proof of death and a valid court order showing you have a legal right to them. Access isn't guaranteed and can take time. Dropbox's own first suggestion is to check the person's computer, where the Dropbox folder often holds a synced copy of every file.",
 facts=["Check the synced folder on their computer first","Needs proof of death + court order","Access not guaranteed","Request via a Dropbox support ticket"],
 need=["Full name and Dropbox email of the deceased","Your name, mailing address, email and relationship","A photocopy of your government ID","A valid court order establishing your right to the files"],
 timeline="Dropbox says these requests 'can take some time' and gives no fixed timeframe.",
 lost=["Files that only exist online, if the request is refused"],
 extra=[("Is there a faster way into Dropbox files?","Yes. Look in the Dropbox folder on the person's computer, which often contains synced copies of everything."),("Does Dropbox have a legacy contact?","No. Requests go through a support ticket with legal documents.")],
 sources=[("Dropbox Help: Access the account of someone who has passed away","https://help.dropbox.com/account-settings/access-account-of-someone-who-passed-away")],related=["/platforms/microsoft-outlook/","/guides/access-deceased-persons-phone-and-accounts/","/platforms/google-photos/"]),
}
